const settingsDefaults={customer:[['交易通知','下单成功',true,false],['交易通知','下单失败',true,true],['交易通知','撤单结果',true,true],['交易通知','改单结果',true,true],['交易通知','成交提醒',true,false],['风控通知','账户风险提醒',true,true],['系统通知','登录提醒',true,false]],trader:[['交易通知','下单待确认',true,true],['交易通知','撤单待确认',true,true],['交易通知','改单待确认',true,true],['交易通知','交易失败与异常',true,true],['交易通知','成交提醒',true,false],['风控通知','账户风险提醒',true,true],['系统通知','登录提醒',true,false]]};
let state={role:location.hash.includes('trader')?'trader':'customer',category:'all',quick:'all',selected:null,query:'',settings:{}};
['customer','trader'].forEach(role=>state.settings[role]=settingsDefaults[role].map(x=>({group:x[0],name:x[1],enabled:x[2],popup:x[3]})));

const colors={success:'#46d39a',error:'#ff6b7d',pending:'#ffb84a',risk:'#ff7f73',info:'#57a6ff'};
const categoryLabels={all:'全部',trade:'交易通知',risk:'风控通知',system:'系统通知'};
function render(){
 const p=profiles[state.role]; document.body.dataset.role=state.role; document.getElementById('workspaceLabel').textContent=p.label; document.getElementById('userName').textContent=p.name; document.getElementById('userRole').textContent=p.role;
 document.querySelectorAll('.role-option').forEach(b=>b.classList.toggle('active',b.dataset.role===state.role));
 document.getElementById('traderControls').hidden=state.role!=='trader'; renderSummary(); renderTabs(); renderQuickFilters(); renderList(); renderSettings();
 location.hash=state.role;
}
function renderSummary(){document.getElementById('summaryGrid').innerHTML=profiles[state.role].summary.map(([label,value,note,ico,color])=>`<div class="summary-card" style="--card-color:${color};--tone:${color}1f"><div class="summary-top"><span>${label}</span><span class="summary-icon">${icon(ico)}</span></div><div class="summary-value">${value}</div><div class="summary-note">${note}</div></div>`).join('')}
function renderTabs(){const data=messages[state.role];document.getElementById('categoryTabs').innerHTML=Object.keys(categoryLabels).map(cat=>{const count=cat==='all'?data.length:data.filter(m=>m.cat===cat).length;return `<button class="tab-button ${state.category===cat?'active':''}" data-category="${cat}" role="tab">${categoryLabels[cat]}<b>${count}</b></button>`}).join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.selected=null;renderTabs();renderList()})}
function renderQuickFilters(){const el=document.getElementById('quickFilters');if(state.role!=='trader'){el.innerHTML='';return}const items=[['all','全部状态'],['pending','待处理'],['error','异常与失败'],['unread','未读']];el.innerHTML=items.map(([k,l])=>`<button class="filter-chip ${state.quick===k?'active':''}" data-quick="${k}">${l}</button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.quick=b.dataset.quick;state.selected=null;renderQuickFilters();renderList()})}
function filtered(){return messages[state.role].filter(m=>{const cat=state.category==='all'||m.cat===state.category;const q=!state.query||`${m.title}${m.preview}${m.order}${m.account}${m.customer||''}`.toLowerCase().includes(state.query.toLowerCase());let quick=true;if(state.role==='trader'){if(state.quick==='pending')quick=m.status==='pending';if(state.quick==='error')quick=m.status==='error'||m.status==='risk';if(state.quick==='unread')quick=m.unread}return cat&&q&&quick})}
function renderList(){const data=filtered(),list=document.getElementById('messageList'),empty=document.getElementById('emptyState');document.getElementById('listCount').textContent=`${data.length} 条消息`;empty.hidden=data.length>0;list.hidden=data.length===0;if(!data.length){document.getElementById('detailPanel').innerHTML='<div class="empty-state"><strong>请选择一条消息</strong><p>消息详情将在此处展示</p></div>';return}if(!state.selected||!data.some(m=>m.id===state.selected))state.selected=data[0].id;list.innerHTML=data.map(m=>`<button class="message-item ${m.id===state.selected?'selected':''}" data-id="${m.id}"><span class="status-icon" style="--status-color:${colors[m.status]}">${icon(m.status)}</span><span><span class="item-top">${m.unread?'<i class="unread-dot"></i>':''}<strong>${m.title}</strong></span><span class="item-preview">${m.preview}</span><span class="item-meta"><i class="meta-pill">${m.type}</i><i>${m.account!=='-'?'账户 '+m.account:''}</i><i>${m.mode!=='-'?m.level+' · '+m.mode:''}</i></span></span><span class="item-side">${m.time}<i class="priority" style="--status-color:${colors[m.status]}">${m.priority}</i></span></button>`).join('');list.querySelectorAll('.message-item').forEach(b=>b.onclick=()=>{state.selected=b.dataset.id;const m=messages[state.role].find(x=>x.id===state.selected);m.unread=false;renderList()});renderDetail(messages[state.role].find(m=>m.id===state.selected));updateUnread()}
function renderDetail(m){if(!m)return;const pending=m.status==='pending';document.getElementById('detailPanel').innerHTML=`<div class="detail-header"><span class="status-icon" style="--status-color:${colors[m.status]}">${icon(m.status)}</span><div class="detail-title"><h2>${m.title}</h2><p>${m.time==='昨天'?'昨天':`今天 ${m.time}`} · ${m.type}${m.order!=='-'?' · 订单 '+m.order:''}</p></div><span class="detail-badge" style="--status-color:${colors[m.status]}">${m.priority}</span></div><div class="detail-content"><p>${m.body}</p><div class="detail-section"><h3>业务信息</h3><div class="data-grid">${m.data.map(([k,v])=>`<div class="data-cell"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div></div>${m.cat==='trade'?`<div class="detail-section"><h3>处理进度</h3><div class="timeline"><div class="timeline-step done">申请已提交</div><div class="timeline-step ${pending?'current':'done'}">${pending?'等待确认':'系统已受理'}</div><div class="timeline-step ${m.status==='success'?'done':''}">${m.status==='success'?'处理完成':'结果返回'}</div></div></div>`:''}<div class="detail-actions"><button class="primary-button" id="primaryAction">${icon('external')}${pending&&state.role==='trader'?'前往处理':'查看相关订单'}</button><button class="ghost-button" id="readAction">${icon('check')}标记为已读</button></div></div>`;document.getElementById('primaryAction').onclick=()=>showToast(pending&&state.role==='trader'?'已定位到待处理订单':'已打开订单详情','原型演示不产生真实业务操作');document.getElementById('readAction').onclick=()=>{m.unread=false;renderList();showToast('已标记为已读','未读数量已更新')}}
function updateUnread(){const n=messages[state.role].filter(m=>m.unread).length;document.getElementById('sideUnread').textContent=n;document.getElementById('sideUnread').hidden=n===0}
function renderSettings(){const groups={};state.settings[state.role].forEach((x,i)=>(groups[x.group]??=[]).push({...x,i}));document.getElementById('settingList').innerHTML=Object.entries(groups).map(([group,items])=>`<section class="setting-group"><h3>${group}</h3>${items.map(x=>`<div class="setting-row"><div class="setting-name"><strong>${x.name}</strong><span>${x.enabled?'消息中心接收':'已关闭'}</span></div><button class="switch ${x.enabled?'on':''}" data-setting="enabled" data-index="${x.i}" aria-label="启用${x.name}"></button><button class="switch ${x.popup?'on':''}" data-setting="popup" data-index="${x.i}" ${x.enabled?'':'disabled'} aria-label="弹窗${x.name}"></button></div>`).join('')}</section>`).join('');document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{const s=state.settings[state.role][+b.dataset.index];if(b.dataset.setting==='enabled'){s.enabled=!s.enabled;if(!s.enabled)s.popup=false}else if(s.enabled)s.popup=!s.popup;renderSettings()})}
function openDrawer(){document.getElementById('settingsBackdrop').hidden=false;document.getElementById('settingsDrawer').classList.add('open');document.getElementById('settingsDrawer').setAttribute('aria-hidden','false')}
function closeDrawer(){document.getElementById('settingsBackdrop').hidden=true;document.getElementById('settingsDrawer').classList.remove('open');document.getElementById('settingsDrawer').setAttribute('aria-hidden','true')}
let toastTimer;function showToast(title,text){const t=document.getElementById('toast');t.querySelector('strong').textContent=title;t.querySelector('p').textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
document.querySelectorAll('.role-option').forEach(b=>b.onclick=()=>{state.role=b.dataset.role;state.category='all';state.quick='all';state.selected=null;state.query='';document.getElementById('searchInput').value='';render()});
document.getElementById('searchInput').oninput=e=>{state.query=e.target.value;state.selected=null;renderList()};document.getElementById('markAllRead').onclick=()=>{filtered().forEach(m=>m.unread=false);renderList();showToast('已全部标记为已读','当前筛选范围内消息已更新')};document.getElementById('refreshList').onclick=()=>{renderList();showToast('列表已刷新','消息状态已同步')};document.getElementById('openSettings').onclick=openDrawer;document.getElementById('closeSettings').onclick=closeDrawer;document.getElementById('settingsBackdrop').onclick=closeDrawer;document.getElementById('saveSettings').onclick=()=>{closeDrawer();showToast('设置已保存','新配置已立即生效')};document.getElementById('resetSettings').onclick=()=>{state.settings[state.role]=settingsDefaults[state.role].map(x=>({group:x[0],name:x[1],enabled:x[2],popup:x[3]}));renderSettings();showToast('已恢复默认设置','保存后将立即生效')};document.getElementById('saveView').onclick=()=>showToast('视图已保存','可从视图列表快速切换');document.getElementById('savedView').onchange=e=>{state.quick=e.target.value;renderQuickFilters();renderList()};
render();
